describe('Prefers Reduced Motion Setting', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should respect user\'s prefers-reduced-motion setting and disable animations', () => {
    // Set the prefers-reduced-motion to no-animations
    cy.window().then((win) => {
      win.localStorage.setItem('prefers_reduced_motion', 'no-animations');
    });

    // Verify the setting is applied
    cy.window().then((win) => {
      expect(win.getItem('prefers_reduced_motion')).to.equal('no-animations');
    });

    // Intercept API call to fetch user settings
    cy.intercept('GET', '/api/user-settings').as('getUserSettings');

    // Wait for the API call
    cy.wait('@getUserSettings');

    // Verify the API returns the reduced motion setting
    cy.get('@getUserSettings').then((interception) => {
      expect(interception.response.body.prefersReducedMotion).to.equal('no-animations');
    });

    // Verify animations are disabled
    cy.get('[data-testid="animated-button"]').should('not.be.visible');
    cy.get('[data-testid="fade-in-modal"]').should('not.exist');
    cy.get('[data-testid="slide-in-sidebar"]').should('not.be.visible');

    // Verify content is still accessible
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('be.visible');
  });

  it('should handle edge case where prefers-reduced-motion is not set', () => {
    // Clear any existing prefers-reduced-motion setting
    cy.window().then((win) => {
      win.localStorage.removeItem('prefers_reduced_motion');
    });

    // Verify the setting is cleared
    cy.window().then((win) => {
      expect(win.getItem('prefers_reduced_motion')).to.be.undefined;
    });

    // Verify default animations are enabled
    cy.get('[data-testid="animated-button"]').should('be.visible');
    cy.get('[data-testid="fade-in-modal"]').should('be.visible');
    cy.get('[data-testid="slide-in-sidebar"]').should('be.visible');

    // Verify user can still interact with the app
    cy.get('[data-testid="animated-button"]').click();
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify user can override the setting
    cy.window().then((win) => {
      win.localStorage.setItem('prefers_reduced_motion', 'no-animations');
    });

    // Verify the setting is applied again
    cy.window().then((win) => {
      expect(win.getItem('prefers_reduced_motion')).to.equal('no-animations');
    });

    // Verify animations are disabled again
    cy.get('[data-testid="animated-button"]').should('not.be.visible');
    cy.get('[data-testid="fade-in-modal"]').should('not.exist');
    cy.get('[data-testid="slide-in-sidebar"]').should('not.be.visible');
  });
});
